namespace zdb {
CWorld::CWorld(const char* name)
	{
		m_camera = NULL;
		m_diInt = NULL;
		m_Wind.Reset();

		m_cellData = NULL;

		m_maxOverlap = 2;

		m_grid = new CGrid();

		SetName(name);

		m_scale = 10.0f;
		m_invscale = 0.1f;
		m_world = this;

		m_diInt = new DiIntersect(1024);
		m_diIntDelayCnt = 0.0f;

		m_gLightDirUpdate = true;
		m_gLightColUpdate = true;

		m_default_soiltype = 0;
		m_default_soiltype_name = NULL;
	}
}

